-- patch_tz_prompts.sql
-- Таблица для хранения промптов / ТЗ (только superadmin)
-- ──────────────────────────────────────────────────────────

-- 1. Таблица
CREATE TABLE IF NOT EXISTS public.tz_prompts (
  id         uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  title      text        NOT NULL,
  content    text        NOT NULL DEFAULT '',
  is_done    boolean     NOT NULL DEFAULT false,
  position   integer     NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- 2. RLS
ALTER TABLE public.tz_prompts ENABLE ROW LEVEL SECURITY;

CREATE POLICY "tz_prompts_superadmin_all" ON public.tz_prompts
  FOR ALL
  USING (
    EXISTS (
      SELECT 1 FROM public.profiles
      WHERE profiles.user_id = auth.uid()
        AND profiles.platform_role = 'superadmin'
    )
  )
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM public.profiles
      WHERE profiles.user_id = auth.uid()
        AND profiles.platform_role = 'superadmin'
    )
  );

-- 3. Первый промпт — ТЗ на разработку модуля FBS
INSERT INTO public.tz_prompts (title, content, position) VALUES (
  'FBS модуль — полное ТЗ на разработку',
  E'## 1. Контекст и бизнес-цель\nВ связи с текущими рисками и нестабильностью на крупных складах маркетплейсов (в частности, Wildberries на территории РФ, где риски инцидентов и закрытия складов переносят нагрузку на селлеров), возрастает критическая актуальность работы по модели FBS (Fulfillment by Seller).\n\nНеобходимо доработать существующий сервис, добавив в него полноценную поддержку FBS-режима, чтобы продавцы могли безопасно хранить товары на собственных/арендованных складах и оперативно комплектовать заказы.\n\n## 2. Текущее состояние системы (Что уже есть)\n* Сервис уже функционирует.\n* Реализован базовый учет и данные по содержанию коробов/упаковки (сборка коробов, стикерование, наполнение).\n* Задача: интегрировать новый модуль FBS в существующую архитектуру, не сломав имеющийся функционал.\n\n## 3. Требования к новому функционалу FBS\n\n### Модуль 1: Адресное хранение (WMS Lite) с визуальным редактором\n1. Иерархия хранения: Склад → Зона → Стеллаж → Ярус/Полка → Ячейка (координатная система, например: A-01-02-03).\n2. Конструктор склада (Визуальное решение):\n   * Возможность пользователю самостоятельно создавать и редактировать структуру склада.\n   * Графическое/интерактивное или табличное представление топологии с координатами.\n   * Визуальное отображение статуса ячеек (занята / свободна / забронирована под сборку).\n3. Привязка товара: Возможность закреплять товары и короба за конкретными ячейками адресного хранения.\n\n### Модуль 2: Интеграция с маркетплейсами по API (Синхронизация FBS)\n1. Сбор заказов (Сборочные задания / Assembly Tasks):\n   * Автоматический импорт поступающих заказов со всех подключенных магазинов/аккаунтов.\n   * Отображение единого реестра FBS-заказов (статусы: Новый, На сборке, Собран, Передан в доставку, Отменен).\n   * Отображение таймеров (SLA) отгрузки, чтобы избежать штрафов маркетплейса.\n2. Синхронизация остатков:\n   * Автоматическое списание/резервирование товара на адресных ячейках при поступлении FBS-заказа.\n   * Передача актуального свободного остатка со склада на маркетплейс по API.\n3. Печать этикеток и документов:\n   * Скачивание и печать маркировок сборочных заданий (стикеры заказов WB) и актов приема-передачи (листов подбора).\n\n### Модуль 3: Биллинг и выставление счетов за услуги FBS\n1. Тарификация операций:\n   * Хранение (расчет стоимости за ячейку / паллету / объем в день).\n   * Обработка и сборка FBS-заказа (Pick & Pack).\n   * Маркировка, стикерование, вкладыши.\n   * Отгрузка / логистика до сортировочного центра (СЦ) или ППЗ.\n2. Формирование счетов:\n   * Автоматическое списание средств с баланса клиента или генерация детализированного акта/счета за период / по факту отгрузки партии FBS-заказов.\n\n## 4. План реализации\n\n1. Архитектура базы данных (PostgreSQL / Supabase):\n   * Схема таблиц для топологии склада (warehouses, zones, racks, cells).\n   * Схема для FBS-заказов (fbs_orders, fbs_order_items, fbs_reservations).\n   * Схема биллинга и услуг (fbs_tariffs, fbs_services_log, invoices).\n2. API Integrations & Workers:\n   * Логика взаимодействия с WB API (методы получения сборочных заданий, обновления остатков, получения этикеток).\n   * Механизм фонового опроса (Cron / Queue) для синхронизации заказов в реальном времени.\n3. Frontend / UI:\n   * Компоненты для визуализации/конструктора ячеек адресного хранения.\n   * UI дашборда заказов FBS с фильтрацией по магазинам и статусам.\n4. Логика резервирования и биллинга:\n   * Алгоритм списывания товара с конкретной ячейки при сборке заказа.',
  0
);
